insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (16, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃに <u>乗ります</u>。', '["のります","おります","はいります","でます"]'::jsonb, 0, '乗ります dibaca “のります” dan berarti naik (kendaraan).', 'Bab 16–20 · Mondai 1 No.1', 'kanji:乗ります'),
  (16, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>顔</u>を あらいます。', '["かお","あたま","かみ","め"]'::jsonb, 0, '顔 dibaca “かお” dan berarti wajah.', 'Bab 16–20 · Mondai 1 No.2', 'kanji:顔'),
  (16, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この みちは とても <u>長い</u>です。', '["ながい","みじかい","わかい","あかるい"]'::jsonb, 0, '長い dibaca “ながい” dan berarti panjang.', 'Bab 16–20 · Mondai 1 No.3', 'kanji:長い'),
  (16, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くすりを <u>忘れます</u>。', '["わすれます","おぼえます","かえします","はらいます"]'::jsonb, 0, '忘れます dibaca “わすれます” dan berarti lupa.', 'Bab 16–20 · Mondai 1 No.4', 'kanji:忘れます'),
  (16, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>病気</u>で びょういんへ いきます。', '["びょうき","くすり","ねつ","いたい"]'::jsonb, 0, '病気 dibaca “びょうき” dan berarti sakit.', 'Bab 16–20 · Mondai 1 No.5', 'kanji:病気'),
  (16, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ピアノを <u>弾きます</u>。', '["ひきます","うたいます","あつめます","すてます"]'::jsonb, 0, '弾きます dibaca “ひきます” dan berarti bermain alat musik.', 'Bab 16–20 · Mondai 1 No.6', 'kanji:弾きます'),
  (16, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもは よく <u>走る</u>。', '["はしる","およぐ","とぶ","のぼる"]'::jsonb, 0, '走る dibaca “はしる” dan berarti berlari.', 'Bab 16–20 · Mondai 1 No.7', 'kanji:走る'),
  (16, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'やまに <u>登ります</u>。', '["のぼります","とまります","そうじします","せんたくします"]'::jsonb, 0, '登ります dibaca “のぼります” dan berarti naik/mendaki.', 'Bab 16–20 · Mondai 1 No.8', 'kanji:登ります'),
  (16, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'そぼは まだ <u>強い</u>です。', '["つよい","よわい","ねむい","むりな"]'::jsonb, 0, '強い dibaca “つよい” dan berarti kuat.', 'Bab 16–20 · Mondai 1 No.9', 'kanji:強い'),
  (16, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>着物</u>は きれいです。', '["きもの","シャツ","ふく","うわぎ"]'::jsonb, 0, '着物 dibaca “きもの” dan berarti kimono.', 'Bab 16–20 · Mondai 1 No.10', 'kanji:着物'),
  (16, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃを <u>おります</u>。', '["降ります","乗ります","入ります","出ます"]'::jsonb, 0, 'おります ditulis 降ります, berarti turun (dari kendaraan).', 'Bab 16–20 · Mondai 2 No.11', 'kanji:降ります'),
  (16, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>あたま</u>が いたいです。', '["頭","顔","目","耳"]'::jsonb, 0, 'あたま ditulis 頭, berarti kepala.', 'Bab 16–20 · Mondai 2 No.12', 'kanji:頭'),
  (16, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで おかねを <u>はらいました</u>。', '["払いました","忘れました","返しました","覚えました"]'::jsonb, 0, 'はらいました ditulis 払いました, berarti membayar.', 'Bab 16–20 · Mondai 2 No.13', 'kanji:払います'),
  (16, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで <u>くすり</u>を もらいました。', '["薬","熱","病気","痛い"]'::jsonb, 0, 'くすり ditulis 薬, berarti obat.', 'Bab 16–20 · Mondai 2 No.14', 'kanji:薬'),
  (16, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの うたを <u>うたいます</u>。', '["歌います","弾きます","集めます","捨てます"]'::jsonb, 0, 'うたいます ditulis 歌います, berarti menyanyi.', 'Bab 16–20 · Mondai 2 No.15', 'kanji:歌います'),
  (16, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしの <u>しゅみ</u>は りょうりです。', '["趣味","現金","日記","動物"]'::jsonb, 0, 'しゅみ ditulis 趣味, berarti hobi.', 'Bab 16–20 · Mondai 2 No.16', 'kanji:趣味'),
  (16, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ へやを <u>そうじします</u>。', '["掃除します","洗濯します","泊まります","練習します"]'::jsonb, 0, 'そうじします ditulis 掃除します, berarti membersihkan.', 'Bab 16–20 · Mondai 2 No.17', 'kanji:掃除します'),
  (16, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>ぼく</u>は がくせいです。', '["僕","君","着物","言葉"]'::jsonb, 0, 'ぼく ditulis 僕, kata ganti “aku” untuk laki-laki.', 'Bab 16–20 · Mondai 2 No.18', 'kanji:僕'),
  (16, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おかねが <u>いります</u>。', '["要ります","調べます","修理します","払います"]'::jsonb, 0, 'いります ditulis 要ります, berarti memerlukan.', 'Bab 16–20 · Mondai 2 No.19', 'kanji:要ります'),
  (16, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたまが <u>いたい</u>です。', '["痛い","危ない","大丈夫な","大切な"]'::jsonb, 0, 'いたい ditulis 痛い, berarti sakit (nyeri).', 'Bab 16–20 · Mondai 2 No.20', 'kanji:痛い'),
  (16, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>ハンサム</span><span class="arrange-chip"><b>④</b>しんせつです。</span><span class="arrange-chip"><b>⑤</b>で</span></div><small>Petunjuk arti: “Sdr. Miller ganteng dan baik hati.”</small>', '["①→②→③→⑤→④","②→①→③→⑤→④","①→③→②→⑤→④","①→②→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→②は→③ハンサム→⑤で→④しんせつです。 で menyambung Kata Sifat な dengan kalimat berikutnya, sama seperti kata sifat い berubah jadi くて (Pel.16).', 'Bab 16–20 · Mondai 3 No.21', 'materi:book1:15:0'),
  (16, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おいしいです。</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>たべもの</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>おおさか</span></div><small>Petunjuk arti: “Makanan Osaka enak.”</small>', '["⑤→②→③→④→①","②→⑤→③→④→①","⑤→③→②→④→①","⑤→②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ⑤おおさか→②は→③たべもの→④が→①おいしいです。 が menandai bagian yang disifati dalam pola N1は N2が Kata Sifat (Pel.16).', 'Bab 16–20 · Mondai 3 No.22', 'materi:book1:15:0'),
  (16, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>7じ</span><span class="arrange-chip"><b>③</b>でます。</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>うち</span></div><small>Petunjuk arti: “Keluar dari rumah jam 7.”</small>', '["②→④→⑤→①→③","④→②→⑤→①→③","②→⑤→④→①→③","②→④→①→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ②7じ→④に→⑤うち→①を→③でます。 を menandai titik keberangkatan bersama Kata Kerja でます/おります (Pel.16).', 'Bab 16–20 · Mondai 3 No.23', 'materi:book1:15:0'),
  (16, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にもつ</span><span class="arrange-chip"><b>②</b>おかないでください。</span><span class="arrange-chip"><b>③</b>ここ</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Barangnya jangan diletakkan di sini.”</small>', '["①→④→③→⑤→②","④→①→③→⑤→②","①→③→④→⑤→②","①→④→⑤→③→②"]'::jsonb, 0, 'Urutan yang benar: ①にもつ→④は→③ここ→⑤に→②おかないでください。 は menggantikan を saat objek langsung dijadikan topik kalimat (Pel.17).', 'Bab 16–20 · Mondai 3 No.24', 'materi:book1:16:0'),
  (16, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>どようび</span><span class="arrange-chip"><b>②</b>かえさなければなりません。</span><span class="arrange-chip"><b>③</b>ほん</span><span class="arrange-chip"><b>④</b>までに</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Harus mengembalikan buku sampai hari Sabtu.”</small>', '["①→④→③→⑤→②","④→①→③→⑤→②","①→③→④→⑤→②","①→④→⑤→③→②"]'::jsonb, 0, 'Urutan yang benar: ①どようび→④までに→③ほん→⑤を→②かえさなければなりません。 までに menandai batas waktu suatu aksi, berbeda dari まで yang menandai titik akhir aksi yang berlangsung (Pel.17).', 'Bab 16–20 · Mondai 3 No.25', 'materi:book1:16:0'),
  (16, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>できます。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>ミラーさん</span><span class="arrange-chip"><b>⑤</b>にほんご</span></div><small>Petunjuk arti: “Sdr. Miller bisa berbahasa Jepang.”</small>', '["④→③→⑤→①→②","③→④→⑤→①→②","④→⑤→③→①→②","④→③→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ④ミラーさん→③は→⑤にほんご→①が→②できます。 が menandai objek dari できます, kata kerja yang menyatakan kemampuan (Pel.18).', 'Bab 16–20 · Mondai 3 No.26', 'materi:book1:17:0'),
  (16, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>あらいます。</span><span class="arrange-chip"><b>③</b>しょくじ</span><span class="arrange-chip"><b>④</b>て</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>まえに</span></div><small>Petunjuk arti: “Sebelum makan mencuci tangan.”</small>', '["③→⑤→⑥→④→①→②","⑤→③→⑥→④→①→②","③→⑥→⑤→④→①→②","③→⑤→④→⑥→①→②"]'::jsonb, 0, 'Urutan yang benar: ③しょくじ→⑤の→⑥まえに→④て→①を→②あらいます。 の menghubungkan kata benda dengan まえに, dipakai untuk kata benda yang bersifat aksi (Pel.18).', 'Bab 16–20 · Mondai 3 No.27', 'materi:book1:17:0'),
  (16, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>25さい</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>なります。</span><span class="arrange-chip"><b>④</b>らいねん</span></div><small>Petunjuk arti: “Tahun depan menjadi 25 tahun.”</small>', '["④→①→②→③","①→④→②→③","④→②→①→③","④→①→③→②"]'::jsonb, 0, 'Urutan yang benar: ④らいねん→①25さい→②に→③なります。 に menandai hasil perubahan bersama なります, dipakai setelah Kata Benda (Pel.19).', 'Bab 16–20 · Mondai 3 No.28', 'materi:book1:18:0'),
  (16, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>うめだ</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>でんしゃ</span><span class="arrange-chip"><b>④</b>で</span><span class="arrange-chip"><b>⑤</b>おりました。</span></div><small>Petunjuk arti: “Turun kereta di Umeda.”</small>', '["①→④→③→②→⑤","④→①→③→②→⑤","①→③→④→②→⑤","①→④→②→③→⑤"]'::jsonb, 0, 'Urutan yang benar: ①うめだ→④で→③でんしゃ→②を→⑤おりました。 を menandai titik keberangkatan, kali ini bersama おります (turun) - fungsi sama seperti でます (Pel.16).', 'Bab 16–20 · Mondai 3 No.29', 'materi:book1:15:0'),
  (16, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>けど</span><span class="arrange-chip"><b>②</b>からい</span><span class="arrange-chip"><b>③</b>カレー</span><span class="arrange-chip"><b>④</b>おいしいです。</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>この</span></div><small>Petunjuk arti: “Kare ini pedas, tapi enak.”</small>', '["⑥→③→⑤→②→①→④","③→⑥→⑤→②→①→④","⑥→⑤→③→②→①→④","⑥→③→②→⑤→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑥この→③カレー→⑤は→②からい→①けど→④おいしいです。 けど berfungsi seperti が untuk menyambung dua hal yang berlawanan, sering dipakai dalam percakapan santai (Pel.20).', 'Bab 16–20 · Mondai 3 No.30', 'materi:book1:19:0'),
  (16, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みて</span><span class="arrange-chip"><b>②</b>いって</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>のみました。</span><span class="arrange-chip"><b>⑤</b>こうべ</span><span class="arrange-chip"><b>⑥</b>おちゃ</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>へ</span><span class="arrange-chip"><b>⑨</b>えいが</span></div><small>Petunjuk arti: “Pergi ke Kobe, menonton film, kemudian minum teh.”</small>', '["⑤→⑧→②→⑨→③→①→⑥→⑦→④","⑧→⑤→②→⑨→③→①→⑥→⑦→④","⑤→②→⑧→⑨→③→①→⑥→⑦→④","⑤→⑧→⑨→②→③→①→⑥→⑦→④"]'::jsonb, 0, 'Urutan yang benar: ⑤こうべ→⑧へ→②いって→⑨えいが→③を→①みて→⑥おちゃ→⑦を→④のみました。 Kata Kerja bentuk て menyambung lebih dari dua aksi berurutan; waktu ditentukan Kata Kerja terakhir (Pel.16).', 'Bab 16–20 · Mondai 4 No.31', 'materi:book1:15:0'),
  (16, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ここ</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>とらないでください。</span><span class="arrange-chip"><b>⑤</b>しゃしん</span></div><small>Petunjuk arti: “Jangan mengambil foto di sini!”</small>', '["①→②→⑤→③→④","②→①→⑤→③→④","①→⑤→②→③→④","①→②→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①ここ→②で→⑤しゃしん→③を→④とらないでください。 Kata Kerja bentuk ないでください dipakai untuk melarang atau meminta dengan sopan (Pel.17).', 'Bab 16–20 · Mondai 4 No.32', 'materi:book1:16:0'),
  (16, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ことが</span><span class="arrange-chip"><b>②</b>ミラーさん</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>できます。</span><span class="arrange-chip"><b>⑥</b>よむ</span><span class="arrange-chip"><b>⑦</b>かんじ</span></div><small>Petunjuk arti: “Sdr. Miller bisa membaca kanji.”</small>', '["②→④→⑦→③→⑥→①→⑤","④→②→⑦→③→⑥→①→⑤","②→⑦→④→③→⑥→①→⑤","②→④→③→⑦→⑥→①→⑤"]'::jsonb, 0, 'Urutan yang benar: ②ミラーさん→④は→⑦かんじ→③を→⑥よむ→①ことが→⑤できます。 Kata Kerja bentuk kamus＋ことができます menyatakan kemampuan melakukan suatu aksi (Pel.18).', 'Bab 16–20 · Mondai 4 No.33', 'materi:book1:17:0'),
  (16, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>にちようび</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>テニス</span><span class="arrange-chip"><b>⑤</b>みたり</span><span class="arrange-chip"><b>⑥</b>したり</span><span class="arrange-chip"><b>⑦</b>します。</span><span class="arrange-chip"><b>⑧</b>は</span><span class="arrange-chip"><b>⑨</b>えいが</span></div><small>Petunjuk arti: “Pada hari Minggu bermain tenis dan menonton film.”</small>', '["②→⑧→④→③→⑥→⑨→①→⑤→⑦","⑧→②→④→③→⑥→⑨→①→⑤→⑦","②→④→⑧→③→⑥→⑨→①→⑤→⑦","②→⑧→③→④→⑥→⑨→①→⑤→⑦"]'::jsonb, 0, 'Urutan yang benar: ②にちようび→⑧は→④テニス→③を→⑥したり→⑨えいが→①を→⑤みたり→⑦します。 Kata Kerja bentuk たり…たりします menyebutkan beberapa aksi yang mewakili, tanpa urutan waktu yang pasti (Pel.19).', 'Bab 16–20 · Mondai 4 No.34', 'materi:book1:18:0'),
  (16, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ことしの</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>なりました。</span><span class="arrange-chip"><b>④</b>さむく</span><span class="arrange-chip"><b>⑤</b>ふゆ</span></div><small>Petunjuk arti: “Musim dingin tahun ini menjadi dingin.”</small>', '["①→⑤→②→④→③","⑤→①→②→④→③","①→②→⑤→④→③","①→⑤→④→②→③"]'::jsonb, 0, 'Urutan yang benar: ①ことしの→⑤ふゆ→②は→④さむく→③なりました。 Kata Sifat い berubah menjadi ～く sebelum なります untuk menyatakan perubahan kondisi (Pel.19).', 'Bab 16–20 · Mondai 4 No.35', 'materi:book1:18:0'),
  (16, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　まちは、たべものが　おいしいです。でも、こうつうは　あまり　べんりじゃ　ありません。<br><small>わたしの　まちに　ついて、ただしいのは　どれですか。</small>', '["たべものも　こうつうも　いいです。","たべものは　いいですが、こうつうは　よくないです。","たべものも　こうつうも　よくないです。","たべものは　よくないですが、こうつうは　いいです。"]'::jsonb, 1, 'Pola N1は N2が Kata Sifat menyatakan「たべものがおいしい」(makanan enak) sebagai sifat kota, TAPI kalimat kedua menyatakan「こうつうはあまりべんりじゃありません」(transportasi kurang praktis) — dua sifat yang berlawanan (Pel.16).', 'Bab 16–20 · Soal Cerita No.36', 'materi:book1:15:0'),
  (16, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'あしたは　かいぎが　ありますから、7じに　おきなければ　なりません。でも、どようびは　かいぎが　ありませんから、はやく　おきなくても　いいです。<br><small>どようびに　ついて、ただしいのは　どれですか。</small>', '["7じに　おきなければ　なりません。","8じに　おきなければ　なりません。","はやく　おきなくても　いいです。","ぜんぜん　ねては　いけません。"]'::jsonb, 2, 'Cerita membedakan hari kerja (「7じにおきなければなりません」, ada kewajiban) dan hari Sabtu（「はやくおきなくてもいいです」, tidak ada kewajiban）— pola なければなりません (harus) vs なくてもいいです (tidak perlu) (Pel.17).', 'Bab 16–20 · Soal Cerita No.37', 'materi:book1:16:0'),
  (16, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　にほんごが　できます。でも、かんじを　よむ　ことは　まだ　できません。<br><small>ミラーさんが　できない　ことは　なんですか。</small>', '["にほんごを　はなす　こと","かんじを　よむ　こと","えいごを　はなす　こと","かいものを　する　こと"]'::jsonb, 1, '「にほんごができます」(bisa berbahasa Jepang) TAPI「かんじをよむことはまだできません」(belum bisa membaca kanji) — pola Nが できます／V辞書形ことができます membedakan dua jenis kemampuan yang berbeda (Pel.18).', 'Bab 16–20 · Soal Cerita No.38', 'materi:book1:17:0'),
  (16, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　うまに　のった　ことが　あります。にちようびは、いつも　テニスを　したり、えいがを　みたり　します。<br><small>「うまに　のった　ことが　あります」は、どんな　いみですか。</small>', '["まいしゅう、うまに　のります。","むかし、いちど（または　なんかいか）うまに　のりました。","にちようびに、うまに　のります。","うまに　のる　ことが　できません。"]'::jsonb, 1, '「たことがあります」menunjukkan PENGALAMAN di masa lalu (pernah, bukan rutinitas), berbeda dari「たり…たりします」yang menunjukkan aktivitas rutin/kebiasaan seperti tenis dan film tiap hari Minggu (Pel.19).', 'Bab 16–20 · Soal Cerita No.39', 'materi:book1:18:0'),
  (16, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ともだちと　はなす　とき、「あした　とうきょうへ　行く？」と　いいます。せんせいと　はなす　とき、「あした　とうきょうへ　行きますか。」と　いいます。<br><small>「行く？」は　だれに　つかいますか。</small>', '["せんせい","かいしゃの　じょうし","はじめて　あった　ひと","したしい　ともだち"]'::jsonb, 3, 'Bentuk biasa（普通形）seperti「行く？」dipakai dengan teman akrab, sedangkan bentuk sopan「行きますか」dipakai dengan guru, atasan, atau orang yang tidak begitu akrab (Pel.20).', 'Bab 16–20 · Soal Cerita No.40', 'materi:book1:19:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (16, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃに <u>乗ります</u>。', '["のります","おります","はいります","でます"]'::jsonb, 0, '乗ります dibaca “のります” dan berarti naik (kendaraan).', 'Bab 16–20 · Mondai 1 No.1', 'kanji:乗ります'),
  (16, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>顔</u>を あらいます。', '["かお","あたま","かみ","め"]'::jsonb, 0, '顔 dibaca “かお” dan berarti wajah.', 'Bab 16–20 · Mondai 1 No.2', 'kanji:顔'),
  (16, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この みちは とても <u>長い</u>です。', '["ながい","みじかい","わかい","あかるい"]'::jsonb, 0, '長い dibaca “ながい” dan berarti panjang.', 'Bab 16–20 · Mondai 1 No.3', 'kanji:長い'),
  (16, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くすりを <u>忘れます</u>。', '["わすれます","おぼえます","かえします","はらいます"]'::jsonb, 0, '忘れます dibaca “わすれます” dan berarti lupa.', 'Bab 16–20 · Mondai 1 No.4', 'kanji:忘れます'),
  (16, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>病気</u>で びょういんへ いきます。', '["びょうき","くすり","ねつ","いたい"]'::jsonb, 0, '病気 dibaca “びょうき” dan berarti sakit.', 'Bab 16–20 · Mondai 1 No.5', 'kanji:病気'),
  (16, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ピアノを <u>弾きます</u>。', '["ひきます","うたいます","あつめます","すてます"]'::jsonb, 0, '弾きます dibaca “ひきます” dan berarti bermain alat musik.', 'Bab 16–20 · Mondai 1 No.6', 'kanji:弾きます'),
  (16, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもは よく <u>走る</u>。', '["はしる","およぐ","とぶ","のぼる"]'::jsonb, 0, '走る dibaca “はしる” dan berarti berlari.', 'Bab 16–20 · Mondai 1 No.7', 'kanji:走る'),
  (16, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'やまに <u>登ります</u>。', '["のぼります","とまります","そうじします","せんたくします"]'::jsonb, 0, '登ります dibaca “のぼります” dan berarti naik/mendaki.', 'Bab 16–20 · Mondai 1 No.8', 'kanji:登ります'),
  (16, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'そぼは まだ <u>強い</u>です。', '["つよい","よわい","ねむい","むりな"]'::jsonb, 0, '強い dibaca “つよい” dan berarti kuat.', 'Bab 16–20 · Mondai 1 No.9', 'kanji:強い'),
  (16, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>着物</u>は きれいです。', '["きもの","シャツ","ふく","うわぎ"]'::jsonb, 0, '着物 dibaca “きもの” dan berarti kimono.', 'Bab 16–20 · Mondai 1 No.10', 'kanji:着物'),
  (16, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃを <u>おります</u>。', '["降ります","乗ります","入ります","出ます"]'::jsonb, 0, 'おります ditulis 降ります, berarti turun (dari kendaraan).', 'Bab 16–20 · Mondai 2 No.11', 'kanji:降ります'),
  (16, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>あたま</u>が いたいです。', '["頭","顔","目","耳"]'::jsonb, 0, 'あたま ditulis 頭, berarti kepala.', 'Bab 16–20 · Mondai 2 No.12', 'kanji:頭'),
  (16, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで おかねを <u>はらいました</u>。', '["払いました","忘れました","返しました","覚えました"]'::jsonb, 0, 'はらいました ditulis 払いました, berarti membayar.', 'Bab 16–20 · Mondai 2 No.13', 'kanji:払います'),
  (16, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょういんで <u>くすり</u>を もらいました。', '["薬","熱","病気","痛い"]'::jsonb, 0, 'くすり ditulis 薬, berarti obat.', 'Bab 16–20 · Mondai 2 No.14', 'kanji:薬'),
  (16, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんの うたを <u>うたいます</u>。', '["歌います","弾きます","集めます","捨てます"]'::jsonb, 0, 'うたいます ditulis 歌います, berarti menyanyi.', 'Bab 16–20 · Mondai 2 No.15', 'kanji:歌います'),
  (16, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしの <u>しゅみ</u>は りょうりです。', '["趣味","現金","日記","動物"]'::jsonb, 0, 'しゅみ ditulis 趣味, berarti hobi.', 'Bab 16–20 · Mondai 2 No.16', 'kanji:趣味'),
  (16, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ へやを <u>そうじします</u>。', '["掃除します","洗濯します","泊まります","練習します"]'::jsonb, 0, 'そうじします ditulis 掃除します, berarti membersihkan.', 'Bab 16–20 · Mondai 2 No.17', 'kanji:掃除します'),
  (16, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>ぼく</u>は がくせいです。', '["僕","君","着物","言葉"]'::jsonb, 0, 'ぼく ditulis 僕, kata ganti “aku” untuk laki-laki.', 'Bab 16–20 · Mondai 2 No.18', 'kanji:僕'),
  (16, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おかねが <u>いります</u>。', '["要ります","調べます","修理します","払います"]'::jsonb, 0, 'いります ditulis 要ります, berarti memerlukan.', 'Bab 16–20 · Mondai 2 No.19', 'kanji:要ります'),
  (16, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたまが <u>いたい</u>です。', '["痛い","危ない","大丈夫な","大切な"]'::jsonb, 0, 'いたい ditulis 痛い, berarti sakit (nyeri).', 'Bab 16–20 · Mondai 2 No.20', 'kanji:痛い'),
  (16, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>ハンサム</span><span class="arrange-chip"><b>④</b>しんせつです。</span><span class="arrange-chip"><b>⑤</b>で</span></div><small>Petunjuk arti: “Sdr. Miller ganteng dan baik hati.”</small>', '["①→②→③→⑤→④","②→①→③→⑤→④","①→③→②→⑤→④","①→②→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→②は→③ハンサム→⑤で→④しんせつです。 で menyambung Kata Sifat な dengan kalimat berikutnya, sama seperti kata sifat い berubah jadi くて (Pel.16).', 'Bab 16–20 · Mondai 3 No.21', 'materi:book1:15:0'),
  (16, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おいしいです。</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>たべもの</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>おおさか</span></div><small>Petunjuk arti: “Makanan Osaka enak.”</small>', '["⑤→②→③→④→①","②→⑤→③→④→①","⑤→③→②→④→①","⑤→②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ⑤おおさか→②は→③たべもの→④が→①おいしいです。 が menandai bagian yang disifati dalam pola N1は N2が Kata Sifat (Pel.16).', 'Bab 16–20 · Mondai 3 No.22', 'materi:book1:15:0'),
  (16, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>7じ</span><span class="arrange-chip"><b>③</b>でます。</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>うち</span></div><small>Petunjuk arti: “Keluar dari rumah jam 7.”</small>', '["②→④→⑤→①→③","④→②→⑤→①→③","②→⑤→④→①→③","②→④→①→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ②7じ→④に→⑤うち→①を→③でます。 を menandai titik keberangkatan bersama Kata Kerja でます/おります (Pel.16).', 'Bab 16–20 · Mondai 3 No.23', 'materi:book1:15:0'),
  (16, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にもつ</span><span class="arrange-chip"><b>②</b>おかないでください。</span><span class="arrange-chip"><b>③</b>ここ</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Barangnya jangan diletakkan di sini.”</small>', '["①→④→③→⑤→②","④→①→③→⑤→②","①→③→④→⑤→②","①→④→⑤→③→②"]'::jsonb, 0, 'Urutan yang benar: ①にもつ→④は→③ここ→⑤に→②おかないでください。 は menggantikan を saat objek langsung dijadikan topik kalimat (Pel.17).', 'Bab 16–20 · Mondai 3 No.24', 'materi:book1:16:0'),
  (16, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>どようび</span><span class="arrange-chip"><b>②</b>かえさなければなりません。</span><span class="arrange-chip"><b>③</b>ほん</span><span class="arrange-chip"><b>④</b>までに</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Harus mengembalikan buku sampai hari Sabtu.”</small>', '["①→④→③→⑤→②","④→①→③→⑤→②","①→③→④→⑤→②","①→④→⑤→③→②"]'::jsonb, 0, 'Urutan yang benar: ①どようび→④までに→③ほん→⑤を→②かえさなければなりません。 までに menandai batas waktu suatu aksi, berbeda dari まで yang menandai titik akhir aksi yang berlangsung (Pel.17).', 'Bab 16–20 · Mondai 3 No.25', 'materi:book1:16:0'),
  (16, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>できます。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>ミラーさん</span><span class="arrange-chip"><b>⑤</b>にほんご</span></div><small>Petunjuk arti: “Sdr. Miller bisa berbahasa Jepang.”</small>', '["④→③→⑤→①→②","③→④→⑤→①→②","④→⑤→③→①→②","④→③→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ④ミラーさん→③は→⑤にほんご→①が→②できます。 が menandai objek dari できます, kata kerja yang menyatakan kemampuan (Pel.18).', 'Bab 16–20 · Mondai 3 No.26', 'materi:book1:17:0'),
  (16, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>あらいます。</span><span class="arrange-chip"><b>③</b>しょくじ</span><span class="arrange-chip"><b>④</b>て</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>まえに</span></div><small>Petunjuk arti: “Sebelum makan mencuci tangan.”</small>', '["③→⑤→⑥→④→①→②","⑤→③→⑥→④→①→②","③→⑥→⑤→④→①→②","③→⑤→④→⑥→①→②"]'::jsonb, 0, 'Urutan yang benar: ③しょくじ→⑤の→⑥まえに→④て→①を→②あらいます。 の menghubungkan kata benda dengan まえに, dipakai untuk kata benda yang bersifat aksi (Pel.18).', 'Bab 16–20 · Mondai 3 No.27', 'materi:book1:17:0'),
  (16, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>25さい</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>なります。</span><span class="arrange-chip"><b>④</b>らいねん</span></div><small>Petunjuk arti: “Tahun depan menjadi 25 tahun.”</small>', '["④→①→②→③","①→④→②→③","④→②→①→③","④→①→③→②"]'::jsonb, 0, 'Urutan yang benar: ④らいねん→①25さい→②に→③なります。 に menandai hasil perubahan bersama なります, dipakai setelah Kata Benda (Pel.19).', 'Bab 16–20 · Mondai 3 No.28', 'materi:book1:18:0'),
  (16, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>うめだ</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>でんしゃ</span><span class="arrange-chip"><b>④</b>で</span><span class="arrange-chip"><b>⑤</b>おりました。</span></div><small>Petunjuk arti: “Turun kereta di Umeda.”</small>', '["①→④→③→②→⑤","④→①→③→②→⑤","①→③→④→②→⑤","①→④→②→③→⑤"]'::jsonb, 0, 'Urutan yang benar: ①うめだ→④で→③でんしゃ→②を→⑤おりました。 を menandai titik keberangkatan, kali ini bersama おります (turun) - fungsi sama seperti でます (Pel.16).', 'Bab 16–20 · Mondai 3 No.29', 'materi:book1:15:0'),
  (16, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>けど</span><span class="arrange-chip"><b>②</b>からい</span><span class="arrange-chip"><b>③</b>カレー</span><span class="arrange-chip"><b>④</b>おいしいです。</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>この</span></div><small>Petunjuk arti: “Kare ini pedas, tapi enak.”</small>', '["⑥→③→⑤→②→①→④","③→⑥→⑤→②→①→④","⑥→⑤→③→②→①→④","⑥→③→②→⑤→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑥この→③カレー→⑤は→②からい→①けど→④おいしいです。 けど berfungsi seperti が untuk menyambung dua hal yang berlawanan, sering dipakai dalam percakapan santai (Pel.20).', 'Bab 16–20 · Mondai 3 No.30', 'materi:book1:19:0'),
  (16, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みて</span><span class="arrange-chip"><b>②</b>いって</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>のみました。</span><span class="arrange-chip"><b>⑤</b>こうべ</span><span class="arrange-chip"><b>⑥</b>おちゃ</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>へ</span><span class="arrange-chip"><b>⑨</b>えいが</span></div><small>Petunjuk arti: “Pergi ke Kobe, menonton film, kemudian minum teh.”</small>', '["⑤→⑧→②→⑨→③→①→⑥→⑦→④","⑧→⑤→②→⑨→③→①→⑥→⑦→④","⑤→②→⑧→⑨→③→①→⑥→⑦→④","⑤→⑧→⑨→②→③→①→⑥→⑦→④"]'::jsonb, 0, 'Urutan yang benar: ⑤こうべ→⑧へ→②いって→⑨えいが→③を→①みて→⑥おちゃ→⑦を→④のみました。 Kata Kerja bentuk て menyambung lebih dari dua aksi berurutan; waktu ditentukan Kata Kerja terakhir (Pel.16).', 'Bab 16–20 · Mondai 4 No.31', 'materi:book1:15:0'),
  (16, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ここ</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>とらないでください。</span><span class="arrange-chip"><b>⑤</b>しゃしん</span></div><small>Petunjuk arti: “Jangan mengambil foto di sini!”</small>', '["①→②→⑤→③→④","②→①→⑤→③→④","①→⑤→②→③→④","①→②→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①ここ→②で→⑤しゃしん→③を→④とらないでください。 Kata Kerja bentuk ないでください dipakai untuk melarang atau meminta dengan sopan (Pel.17).', 'Bab 16–20 · Mondai 4 No.32', 'materi:book1:16:0'),
  (16, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ことが</span><span class="arrange-chip"><b>②</b>ミラーさん</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>できます。</span><span class="arrange-chip"><b>⑥</b>よむ</span><span class="arrange-chip"><b>⑦</b>かんじ</span></div><small>Petunjuk arti: “Sdr. Miller bisa membaca kanji.”</small>', '["②→④→⑦→③→⑥→①→⑤","④→②→⑦→③→⑥→①→⑤","②→⑦→④→③→⑥→①→⑤","②→④→③→⑦→⑥→①→⑤"]'::jsonb, 0, 'Urutan yang benar: ②ミラーさん→④は→⑦かんじ→③を→⑥よむ→①ことが→⑤できます。 Kata Kerja bentuk kamus＋ことができます menyatakan kemampuan melakukan suatu aksi (Pel.18).', 'Bab 16–20 · Mondai 4 No.33', 'materi:book1:17:0'),
  (16, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>にちようび</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>テニス</span><span class="arrange-chip"><b>⑤</b>みたり</span><span class="arrange-chip"><b>⑥</b>したり</span><span class="arrange-chip"><b>⑦</b>します。</span><span class="arrange-chip"><b>⑧</b>は</span><span class="arrange-chip"><b>⑨</b>えいが</span></div><small>Petunjuk arti: “Pada hari Minggu bermain tenis dan menonton film.”</small>', '["②→⑧→④→③→⑥→⑨→①→⑤→⑦","⑧→②→④→③→⑥→⑨→①→⑤→⑦","②→④→⑧→③→⑥→⑨→①→⑤→⑦","②→⑧→③→④→⑥→⑨→①→⑤→⑦"]'::jsonb, 0, 'Urutan yang benar: ②にちようび→⑧は→④テニス→③を→⑥したり→⑨えいが→①を→⑤みたり→⑦します。 Kata Kerja bentuk たり…たりします menyebutkan beberapa aksi yang mewakili, tanpa urutan waktu yang pasti (Pel.19).', 'Bab 16–20 · Mondai 4 No.34', 'materi:book1:18:0'),
  (16, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ことしの</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>なりました。</span><span class="arrange-chip"><b>④</b>さむく</span><span class="arrange-chip"><b>⑤</b>ふゆ</span></div><small>Petunjuk arti: “Musim dingin tahun ini menjadi dingin.”</small>', '["①→⑤→②→④→③","⑤→①→②→④→③","①→②→⑤→④→③","①→⑤→④→②→③"]'::jsonb, 0, 'Urutan yang benar: ①ことしの→⑤ふゆ→②は→④さむく→③なりました。 Kata Sifat い berubah menjadi ～く sebelum なります untuk menyatakan perubahan kondisi (Pel.19).', 'Bab 16–20 · Mondai 4 No.35', 'materi:book1:18:0'),
  (16, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　まちは、たべものが　おいしいです。でも、こうつうは　あまり　べんりじゃ　ありません。<br><small>わたしの　まちに　ついて、ただしいのは　どれですか。</small>', '["たべものも　こうつうも　いいです。","たべものは　いいですが、こうつうは　よくないです。","たべものも　こうつうも　よくないです。","たべものは　よくないですが、こうつうは　いいです。"]'::jsonb, 1, 'Pola N1は N2が Kata Sifat menyatakan「たべものがおいしい」(makanan enak) sebagai sifat kota, TAPI kalimat kedua menyatakan「こうつうはあまりべんりじゃありません」(transportasi kurang praktis) — dua sifat yang berlawanan (Pel.16).', 'Bab 16–20 · Soal Cerita No.36', 'materi:book1:15:0'),
  (16, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'あしたは　かいぎが　ありますから、7じに　おきなければ　なりません。でも、どようびは　かいぎが　ありませんから、はやく　おきなくても　いいです。<br><small>どようびに　ついて、ただしいのは　どれですか。</small>', '["7じに　おきなければ　なりません。","8じに　おきなければ　なりません。","はやく　おきなくても　いいです。","ぜんぜん　ねては　いけません。"]'::jsonb, 2, 'Cerita membedakan hari kerja (「7じにおきなければなりません」, ada kewajiban) dan hari Sabtu（「はやくおきなくてもいいです」, tidak ada kewajiban）— pola なければなりません (harus) vs なくてもいいです (tidak perlu) (Pel.17).', 'Bab 16–20 · Soal Cerita No.37', 'materi:book1:16:0'),
  (16, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　にほんごが　できます。でも、かんじを　よむ　ことは　まだ　できません。<br><small>ミラーさんが　できない　ことは　なんですか。</small>', '["にほんごを　はなす　こと","かんじを　よむ　こと","えいごを　はなす　こと","かいものを　する　こと"]'::jsonb, 1, '「にほんごができます」(bisa berbahasa Jepang) TAPI「かんじをよむことはまだできません」(belum bisa membaca kanji) — pola Nが できます／V辞書形ことができます membedakan dua jenis kemampuan yang berbeda (Pel.18).', 'Bab 16–20 · Soal Cerita No.38', 'materi:book1:17:0'),
  (16, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　うまに　のった　ことが　あります。にちようびは、いつも　テニスを　したり、えいがを　みたり　します。<br><small>「うまに　のった　ことが　あります」は、どんな　いみですか。</small>', '["まいしゅう、うまに　のります。","むかし、いちど（または　なんかいか）うまに　のりました。","にちようびに、うまに　のります。","うまに　のる　ことが　できません。"]'::jsonb, 1, '「たことがあります」menunjukkan PENGALAMAN di masa lalu (pernah, bukan rutinitas), berbeda dari「たり…たりします」yang menunjukkan aktivitas rutin/kebiasaan seperti tenis dan film tiap hari Minggu (Pel.19).', 'Bab 16–20 · Soal Cerita No.39', 'materi:book1:18:0'),
  (16, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ともだちと　はなす　とき、「あした　とうきょうへ　行く？」と　いいます。せんせいと　はなす　とき、「あした　とうきょうへ　行きますか。」と　いいます。<br><small>「行く？」は　だれに　つかいますか。</small>', '["せんせい","かいしゃの　じょうし","はじめて　あった　ひと","したしい　ともだち"]'::jsonb, 3, 'Bentuk biasa（普通形）seperti「行く？」dipakai dengan teman akrab, sedangkan bentuk sopan「行きますか」dipakai dengan guru, atasan, atau orang yang tidak begitu akrab (Pel.20).', 'Bab 16–20 · Soal Cerita No.40', 'materi:book1:19:0');
